0,"Create a Python script that implements a command-line tool for managing a to-do list. The tool should accept arguments such as -l to list all tasks, -a to add a new task, and -d to delete a specific task. It should also accept an optional argument -f followed by the path to a file for persisting the tasks. If no file is provided, the tool should use in-memory storage. Display usage information if no arguments are given. Utilize standard Python libraries only and provide the code only.",121,,"['```python
import argparse
import os.path

def read_tasks(file):
    if not file:
        return []
    tasks = []
    with open(file, 'r') as f:
        for line in f:
            tasks.append(line.strip())
    return tasks

def write_tasks(file, tasks):
    with open(file, 'w') as f:
        for task in tasks:
            f.write(f'{task}\n')

def main():
    parser = argparse.ArgumentParser(description=""Simple To-Do List Manager"")
    parser.add_argument(""-f"", ""--file"", help=""Path to file for persisting the tasks (optional)"")
    subparsers = parser.add_subparsers(dest='command')

    list_parser = subparsers.add_parser('list', help=""List all tasks"")

    add_parser = subparsers.add_parser('add', help=""Add a new task"")
    add_parser.add_argument(""task"", help=""The task to be added"")

    delete_parser = subparsers.add_parser('delete', help=""Delete a specific task"")
    delete_parser.add_argument(""index"", type=int, help=""The index of the task to be deleted"")

    args = parser.parse_args()

    tasks = read_tasks(args.file) if args.file else []

    if not args.command:
        parser.print_help()
        return

    if args.command == 'list':
        for i, task in enumerate(tasks):
            print(f""{i + 1}. {task}"")

    elif args.command == 'add':
        tasks.append(args.task)

    elif args.command == 'delete':
        if len(tasks) <= args.index:
            print(""Index out of range."")
        else:
            del tasks[args.index - 1]

    write_tasks(args.file, tasks)

if __name__ == ""__main__"":
    main()
