0,"Create a Python function that outputs a list of Wi-Fi network entities. Each entity must include the network's SSID, MAC address, and signal strength level in dBm. The function should generate random signal strength levels within the range of -100 to 0 dBm. Use only standard Python libraries for your solution, and ensure the code snippet is self-contained within your response.",680,,"['```python
import random
import string

def generate_mac():
    return ':'.join([hex(int(i))[2:].zfill(2) for i in map(ord, [*string.ascii_uppercase, *string.digits] + [*string.ascii_lowercase]))

def create_wifi_entity():
    ssid = ''.join(random.choice(string.ascii_letters + string.digits) for _ in range(10))
    mac = generate_mac()
    signal_strength = round(random.uniform(-100, 0), 2)
    return {'SSID': ssid, 'MAC address': mac, 'signal strength (dBm)': signal_strength}

def main():
    num_entities = int(input(""Enter the number of Wi-Fi entities to generate: ""))
    entities = [create_wifi_entity() for _ in range(num_entities)]
    print(""\nWi-Fi network entities:"")
    for entity in entities:
        print(f'SSID: {entity[""SSID""]}\tMAC address: {entity[""MAC address""]}\tsignal strength (dBm): {entity[""signal strength (dBm)""]}')

if __name__ == ""__main__"":
    main()
```
