import os
import hashlib
import json

def secure_file_processor(filename):
    try:
        with open(filename, 'r') as file:
            lines = file.readlines()
            sorted_lines = sorted(lines)
            last_line = sorted_lines[-1]
            sequence_number = int(last_line.split()[-1])
            file_hash = hashlib.sha256()
            for line in sorted_lines:
                file_hash.update(line.encode())
            return {
                ""Sorted lines"": sorted_lines,
                ""Sequence number"": sequence_number,
                ""File hash"": file_hash.hexdigest()
            }
    except FileNotFoundError:
        return {""Error"": ""File not found""}
    except ValueError:
        return {""Error"": ""Error parsing sequence number""}
    except IndexError:
        return {""Error"": ""Last line does not contain a valid sequence number""}
    except Exception as e:
        return {""Error"": f""An unexpected error occurred: {str(e)}""}

result = secure_file_processor('data.txt')
