0,"Create a Python program that reads a JSON configuration file and parses its contents. The program should identify and extract all the settings under the ""database"" section. It then uses the extracted database settings to establish a connection with an SQL database. The program must implement error handling for potential connection failures and invalid configurations. Additionally, it should provide functionality to execute SQL queries based on user input, returning relevant data from the connected database. The output of each query execution should be formatted and displayed in a human-readable format.",121,,"['```python
import json
import sqlite3
from sqlite3 import Error

def get_database_config(config_file):
    with open(config_file) as f:
        config = json.load(f)
    database = next((section for section in config if section == ""database""), None)

    if not database:
        raise ValueError(""Invalid configuration, no 'database' section found."")

    return database

def establish_connection(db_config):
    conn = None
    try:
        conn = sqlite3.connect(db_config[""file""])
        print(""Successfully connected to SQLite database."")
    except Error as e:
        print(e)

    if not conn:
        raise Exception(""Unable to establish a connection with the SQLite database."")

    return conn

def execute_query(conn, query):
    cursor = conn.cursor()
    try:
        cursor.execute(query)
        results = cursor.fetchall()

        header = [description[0] for description in cursor.description]
        output = [dict(zip(header, row)) for row in results]

        return output
    except Error as e:
        print(e)

def main():
    config_file = ""config.json""
    db_config = get_database_config(config_file)
    conn = establish_connection(db_config)

    while True:
        query = input(""Enter SQL query or type 'exit' to quit: "")

        if query.lower() == ""exit"":
            break

        results = execute_query(conn, query)

        for row in results:
            print(f""\n{row}"")

if __name__ == ""__main__"":
    main()
```']",137,[0],[],True,0,0,0,

