The script should handle various XML structures and ensure proper error management during parsing and aggregation steps.",120,,"[""```python
import os
import csv
from xml.etree.ElementTree import parse

def average_data(filepath):
    data = {}
    total = 0
    count = 0

    try:
        tree = parse(filepath)
        root = tree.getroot()

        for category in root.iter('category'):
            for value in category.iter('value'):
                if value.text.isdigit():
                    total += float(value.text)
                    count += 1

        if count > 0:
            data[category.get('name')] = total / count

        return data

    except Exception as e:
        print(f'Error processing {filepath}: {str(e)}')
        return {}

def extract_and_save(directory):
    output_file = 'output.csv'
    headers = ['Category', 'Average']

    data = {}
    with open(output_file, 'w', newline='') as csvfile:
        writer = csv.DictWriter(csvfile, fieldnames=headers)
        writer.writeheader()

        for filename in os.listdir(directory):
            if filename.endswith('.xml'):
                filepath = os.path.join(directory, filename)
                category_data = average_data(filepath)

                for category, avg in category_data.items():
                    if category not in data:
                        data[category] = []
                    data[category].append({'Average': avg})

        for category, values in data.items():
            writer.writerows(values)

if __name__ == '__main__':
    directory = './xml_files'  # Replace with your directory path
    extract_and_save(directory)
