1,"Create a Python function that outputs a list of Wi-Fi network entities. Each entity should contain the SSID, MAC address, and a random signal strength level (dBm) between -100 and 0. Use only standard libraries.",680,,"[""```python
import random, string, itertools

def generate_ssid():
    return ''.join(random.choice(string.ascii_uppercase + string.digits) for _ in range(8))

def generate_mac():
    return ':'.join(f'{v:02x}' for v in itertools.islice(itertools.chain([ random.randint(0, 255) for _ in range(6)]), 6))

def generate_signal_strength():
    return round(-random.uniform(100, 0), 2)

def create_wifi_entity():
    ssid = generate_ssid()
    mac = generate_mac()
    signal = generate_signal_strength()
    return {'SSID': ssid, 'MAC Address': mac, 'Signal Strength (dBm)': signal}

def create_wifi_entities(amount=10):
    return [create_wifi_entity() for _ in range(amount)]
