0,"Design and implement a program that creates a simulated library system. The system should generate random ISBN numbers for books, assign unique titles and authors for each book, and provide the option to add or remove books from the library. The program should display the complete list of books in the library to the user upon request.",680,,"['```python
import random

class Book:
    def __init__(self, title, author):
        self.title = title
        self.author = author
        self.isbn = str(random.randint(100_000_000_000, 999_999_999_999))

class Library:
    def __init__(self):
        self.books = []

    def add_book(self, book):
        if book not in self.books:
            self.books.append(book)

    def remove_book(self, book):
        if book in self.books:
            self.books.remove(book)

    def display_library(self):
        for book in self.books:
            print(f""Title: {book.title}, Author: {book.author}, ISBN: {book.isbn}"")

def main():
    library = Library()

    # Add some sample books to the library
    library.add_book(Book(""The Catcher in the Rye"", ""J.D. Salinger""))
    library.add_book(Book(""To Kill a Mockingbird"", ""Harper Lee""))
    library.add_book(Book(""Pride and Prejudice"", ""Jane Austen""))

    # Display the library
    library.display_library()

    # Add new book to the library
    new_book = Book(""New Book"", ""Author"")
    library.add_book(new_book)
    print(""\nAdded New Book:"")
    library.display_library()

    # Remove a book from the library
    remove_book = Book(""To Kill a Mockingbird"", ""Harper Lee"")
    library.remove_book(remove_book)
    print(""\nRemoved Book:"")
    library.display_library()

if __name__ == ""__main__"":
    main()
