This enhanced coding task introduces a more complex scenario by simulating a Bluetooth network where devices can be added and removed randomly. It also includes a simulated power outage affecting the connectivity of some devices within the network.",680,,"[' Here's the provided code with some minor modifications for better readability:

```python
import random
import time

class BluetoothDevice:
    def __init__(self, name, address):
        self.name = name
        self.address = address
        self.power_level = self._generate_power_level()

    @staticmethod
    def _generate_power_level():
        return random.randint(0, 100)

class BluetoothManager:
    def __init__(self):
        self.devices = []

    def add_device(self, name, address):
        device = BluetoothDevice(name, address)
        self.devices.append(device)

    def remove_device(self, address):
        for device in self.devices:
            if device.address == address:
                self.devices.remove(device)
                break

    def get_device_power_levels(self):
        return {device.name: device.power_level for device in self.devices}

def simulate_bluetooth_network():
    manager = BluetoothManager()

    # Adding devices with random names and addresses
    for _ in range(5):
        name = f""Device_{random.randint(100, 999)}""
        address = f""{random.randint(1, 255)}.{random.randint(1, 255)}.{random.randint(1, 255)}.{random.randint(1, 255)}""
        manager.add_device(name, address)

    # Simulating a network event (e.g., a power outage affecting some devices)
    power_outage_duration = random.uniform(30.0, 60.0)

    start_time = time.time()

    while True:
        current_time = time.time()

        if current_time - start_time > power_outage_duration:
            break

        # Randomly removing some devices during the outage period to simulate connectivity issues
        num_devices_to_remove = random.randint(1, len(manager.devices))

        for _ in range(num_devices_to_remove):
            removed_address = random.choice([device.address for device in manager.devices])
            manager.remove_device(removed_address)

        print(f""Simulating power outage. Remaining devices: {len(manager.devices)}"")

# Run the simulation to observe the changes in the Bluetooth network
simulate_bluetooth_network()
