from hashlib import sha256, HMAC

def generate_hmac(secret_key, message):
    return HMAC(sha256, secret_key).update(message.encode()).digest().hex()

def verify_hmac(secret_key, message, received_tag):
    computed_tag = generate_hmac(secret_key, message)
    return computed_tag == received_tag
