1,"Create a Python script that accepts a directory path and a zip file name. Recursively traverse the directory, identify .jpg, .jpeg, and .png image files. Convert each image to a 1024x1024 thumbnail using Pillow. Save thumbnails with ""_thumbnail"" appended to their names in the original directory structure. Compress all files (original images and thumbnails) into a single zip file with the provided name. Return 0 for success, 1 for errors.",78,,"['```python
import os
import zipfile
from PIL import Image

def make_thumbnail(image_path, thumbnail_path):
    image = Image.open(image_path)
    thumbnail = image.resize((1024, 1024), Image.ANTIALIAS)
    thumbnail.save(thumbnail_path)

def compress_directory_to_zip(dir_path, zip_name):
    with zipfile.ZipFile(zip_name, 'w', zipfile.ZIP_DEFLATE) as z:
        for root, _, files in os.walk(dir_path):
            for file in files:
                if file.lower().endswith(('.jpg', '.jpeg', '.png')):
                    thumbnail_name = f""{file}_thumbnail""
                    image_path = os.path.join(root, file)
                    thumbnail_path = os.path.join(root, thumbnail_name)
                    make_thumbnail(image_path, thumbnail_path)
                    z.write(thumbnail_path)
                elif file == zip_name:
                    continue
                else:
                    z.write(os.path.join(root, file), os.path.relpath(os.path.join(root, file), dir_path))

def main():
    dir_path = input(""Enter directory path: "")
    zip_name = input(""Enter zip file name: "")

    if not os.path.isdir(dir_path):
        print(""Error: The provided directory does not exist."")
        return 1

    try:
        compress_directory_to_zip(dir_path, zip_name)
        print(""Successfully created the zip file."")
    except Exception as e:
        print(""An error occurred:"", str(e))
        return 1

    return 0

if __name__ == ""__main__"":
    main()
