def generate_device_id():
    return hashlib.sha256((os.urandom(32)).hex()).hexdigest()

def add_device(name, ip):
    conn = sqlite3.connect('devices.db')
    cursor = conn.cursor()
    device_id = generate_device_id()
    query = ""INSERT INTO devices (id, name, ip) VALUES (?, ?, ?)""
    cursor.execute(query, (device_id, name, ip))
    conn.commit()
    conn.close()

def get_device(ip):
    conn = sqlite3.connect('devices.db')
    cursor = conn.cursor()
    query = ""SELECT * FROM devices WHERE ip=?""
    cursor.execute(query, (ip,))
    result = cursor.fetchone()
    conn.close()
    return result
