    ]

def initialize_objects(objects, callback=None, min_val=(0, 0.0, b'\x00' * 8192), max_val=(10000, 1.0, b'\xff' * 8192)):
    for obj in objects:
        if callback is not None:
            obj._fields_[0] = callback(obj._fields_[0])
            obj._fields_[1] = callback(obj._fields_[1])
            obj._fields_[2] = (c_char * 8192).from_buffer(obj._fields_[2]).cast(""P"" + str(len(obj._fields_[2])) + ""s"").raw.decode()
        else:
