            obj._fields_[1] = random.uniform(min_val[1], max_val[1])
            obj._fields_[2] = (c_char * 8192).from_buffer(obj._fields_[2]).cast(""P"" + str(len(obj._fields_[2])) + ""s"").raw.decode()

def compute_file_hash(file_path, chunk_size=65536):
    with open(file_path, 'rb') as file:
        hash_md5 = hashlib.md5()
        while True:
            data = file.read(chunk_size)
            if not data:
                break
            hash_md5.update(data)
    return hash_md5.hexdigest()

def compute_hashes_for_file(file_path, object_size=8192, min_val=(0, 0.0, b'\x00' * 8192), max_val=(10000, 1.0, b'\xff' * 8192)):
    objects = create_string_buffer(len(CustomObject) * object_size)
    num_objects = int(object_size / len(CustomObject))

    if callback is not None:
        initialize_objects(cast(objects, POINTER(CustomObject)), callback, min_val=min_val[0], max_val=max_val[0])

    cumulative_hash = hashlib.md5()

    for i in range(num_objects):
        current_obj = CustomObject(*unpack(byref(cast(objects, POINTER(CustomObject)).contents)))

        file_chunk_hash = compute_file_hash(file_path=file_path[i*object_size: (i+1)*object_size])
        cumulative_hash.update(file_chunk_hash.encode())

        print(f""Hash of {i}th object: {file_chunk_hash}"")
    return cumulative_hash.hexdigest()
