import random
import string
from cryptography.fernet import Fernet
from hashlib import sha256

class CustomObject:
    def __init__(self, size):
        self.data = [None] * size

def create_custom_object(size):
    custom_obj = CustomObject(size)
    for i in range(size):
        custom_obj.data[i] = ''.join(random.choice(string.ascii_letters + string.digits + '!@#$%&*') for _ in range(10))
    return custom_obj

def encrypt_data(data, key):
    f = Fernet(key)
    encrypted = [f.encrypt(data[i].encode()).decode() for i in range(len(data))]
    return encrypted

def main():
    custom_obj = create_custom_object(5)
    key = Fernet.generate_key()
    encrypted_data = encrypt_data(custom_obj.data, key)

if __name__ == ""__main__"":
    main()
