```",89,,"[' ```python
def enhanced_build_json_object(key_value_pairs, initial_json=None, path_separator='.'):

    if initial_json is None:
        initial_json = {}

    if not isinstance(path_separator, str) or len(path_separator) != 1:
        raise ValueError(""Path separator must be a single character string."")

    def add_pair(key, value, nested_path=''):
        if isinstance(value, (dict, list)):  # Check if value is another dictionary or list
            for k in value.keys():  # Iterate through keys of the nested object
                add_pair(k, value[k], f'{nested_path}{path_separator}')
        else:
            key_list = nested_path.split(path_separator)
            current_obj = initial_json
            for part in key_list[:-1]:  # Iterate through all but the last part of the path
                if part not in current_obj:
                    raise KeyError(f""Invalid key '{part}' in the given JSON object."")
                current_obj = current_obj[part]
            if len(key_list) > 1 and key not in current_obj:  # Check if last part is a valid key
                raise KeyError(f""Invalid key '{key}' at path '{nested_path}{key_list[-1]}'."")
            current_obj[key] = value

    for pair in key_value_pairs:
        key, value = pair
        add_pair(key, value)

    return initial_json
