import geopandas as gpd
import json

def read_json_geo(filepath):
    with open(filepath, 'r') as f:
        data = json.load(f)

    geo_data = []

    for item in data:
        try:
            lat, lon, alt = float(item['lat']), float(item['lon']), float(item['alt'])
            point = gpd.GeoSeries(gpd.points_from_xy([lon, lat], [alt]))
            geo_data.append({'geometry': point})
        except KeyError:
            continue
        except ValueError:
            pass

    return gpd.GeoDataFrame(geo_data)
