import argparse
import os.path

def read_tasks(file):
    if not file:
        return {}

    tasks = {}
    with open(file, 'r') as f:
        for line in f:
            key, value = line.strip().split(':')
            tasks[key] = value
    return tasks

def write_tasks(tasks, file):
    if not file:
        return

    with open(file, 'w') as f:
        for key, value in tasks.items():
            f.write(f'{key}: {value}\n')

def list_tasks(tasks):
    print(""\nTasks:"")
    for key, value in tasks.items():
        print(f""{key}: {value}"")

def add_task(tasks, task):
    tasks[len(tasks)] = task

def delete_task(tasks, index):
    del tasks[index]

def main():
    parser = argparse.ArgumentParser()
    parser.add_argument('-l', '--list', action='store_true')
    parser.add_argument('-a', '--add')
    parser.add_argument('-d', '--delete')
    parser.add_argument('-f', '--file', type=str)

    args = parser.parse_args()

    if not args.list and not args.add and not args.delete:
        print(__doc__)
        return

    tasks = read_tasks(args.file)

    if args.add:
        add_task(tasks, args.add)

    if args.delete:
        try:
            delete_index = int(args.delete)
            delete_task(tasks, delete_index)
        except ValueError:
            print(""Invalid index for deleting task."")

    write_tasks(tasks, args.file)
    list_tasks(tasks)

if __name__ == ""__main__"":
    main()
