import time
import random

class NFAPI_INDICATION_PDU_T:
    def __init__(self, tag, ue_id, signaling_flag):
        self.tag = tag
        self.ue_id = ue_id
        self.signaling_flag = signaling_flag

def generate_time_seed():
    return int(time.time() * 1000)

def allocate_memory(size):
    return [None] * size

def populate_pdu_array(pdu_array):
    for i in range(len(pdu_array)):
        tag = random.randint(1, 65535)
        ue_id = random.randint(0, 1023)
        signaling_flag = bool(random.getrandbits(1))
        pdu_array[i] = NFAPI_INDICATION_PDU_T(tag, ue_id, signaling_flag)

def free_memory(pdu_array):
    del pdu_array

def main():
    array_size = 10
    time_seed = generate_time_seed()
    print(f""Time seed: {time_seed}"")

    pdu_array = allocate_memory(array_size)

    populate_pdu_array(pdu_array)

    for pdu in pdu_array:
        print(f""Tag: {pdu.tag}, UE ID: {pdu.ue_id}, Signaling Flag: {pdu.signaling_flag}"")

    free_memory(pdu_array)

if __name__ == ""__main__"":
    main()
