```python
import os
import hashlib
import json
import re

def process_secure_file(filename, max_lines=100, encoding='utf-8', hash_algorithm='sha256', sequence_regex=r'\d+', sort_key=None):
    try:
        with open(filename, 'r', encoding=encoding) as file:
            lines = [line.strip() for line in file.readlines()[:max_lines]]

            if sort_key:
                sorted_lines = sorted(lines, key=sort_key)
            else:
                sorted_lines = sorted(lines)

            last_line_match = re.search(sequence_regex, sorted_lines[-1])
            if last_line_match:
                sequence_number = int(last_line_match.group())
            else:
                return {""Error"": ""Last line does not contain a valid sequence number""}

            if hash_algorithm == 'sha256':
                hasher = hashlib.sha256()
            elif hash_algorithm == 'md5':
                hasher = hashlib.md5()

            for line in sorted_lines:
                hasher.update(line.encode())

            return {
                ""Sorted lines"": sorted_lines,
                ""Sequence number"": sequence_number,
                ""File hash"": hasher.hexdigest(),
                ""Total Lines Read"": len(lines),
                ""Max Lines Read"": max_lines
            }
    except FileNotFoundError as e:
        return {""Error"": f""File not found: {str(e)}""}
    except ValueError as e:
        return {""Error"": f""Error parsing sequence number: {str(e)}""}
