import argparse
from typing import List

def read_tasks(filepath: str) -> List[str]:
    if filepath:
        try:
            with open(filepath, 'r') as f:
                tasks = [line.strip() for line in f]
        except FileNotFoundError:
            tasks = []
    else:
        tasks = []
    return tasks

def write_tasks(tasks: List[str], filepath: str):
    with open(filepath, 'w') as f:
        [f.write(task + '\n') for task in tasks]

def add_task(tasks: List[str], task: str) -> List[str]:
    return tasks + [task]

def delete_task(tasks: List[str], index: int) -> List[str]:
    if 0 < index <= len(tasks):
        del tasks[index - 1]
    return tasks

def list_tasks(tasks: List[str]) -> None:
    for i, task in enumerate(tasks, start=1):
        print(f'{i}. {task}')

def main():
    parser = argparse.ArgumentParser()
    parser.add_argument('-l', action='store_true')
    parser.add_argument('-a', nargs=1)
    parser.add_argument('-d', type=int, nargs=1)
    parser.add_argument('-f', default=None)
    args = parser.parse_args()

    tasks = read_tasks(args.f)

    if not args.l and not args.a and not args.d:
        parser.print_help()
        return

    if args.a:
        add_task(tasks, args.a[0])
    elif args.d:
        list_tasks(tasks)
        del_index = args.d[0]
        tasks = delete_task(tasks, del_index)

    write_tasks(tasks, args.f)
    list_tasks(tasks)

if __name__ == '__main__':
    main()
