import os
import random
import string
from datetime import datetime

def create_directory(dir_path):
    if not os.path.exists(dir_path):
        os.makedirs(dir_path)

def generate_random_text(length, characters=string.ascii_lowercase + string.digits):
    return ''.join(random.choice(characters) for _ in range(length))

def seed_rng():
    random.seed(datetime.now().timestamp())

def write_files(dir_path, file_count, length, extension=""txt""):
    create_directory(dir_path)

    for i in range(file_count):
        filename = f""{i}.{extension}""
        file_path = os.path.join(dir_path, filename)
        with open(file_path, ""w"") as f:
            f.write(generate_random_text(length))

def read_files(dir_path, extension=""txt""):
    data = {}
    for file in os.listdir(dir_path):
        if file.endswith(extension):
            file_path = os.path.join(dir_path, file)
            with open(file_path, ""r"") as f:
                data[file] = f.read()
    return data

def compare_files(original, generated):
    for file in original.keys():
        if file in generated and original[file] == generated[file]:
            print(f""File {file} matches."")
        else:
            print(f""File {file} does not match."")

