import subprocess

def get_bluetooth_devices():
    # Run the bluetoothctl command on Linux to get the list of paired devices
    output = subprocess.check_output(""bluetoothctl paired-devices"", shell=True, universal_newlines=True)

    lines = output.split('\n')
    devices = []

    for line in lines:
        if 'Device' in line:
            device = {}
            device['name'] = line.strip().split(': ')[1]
            devices.append(device)

    return devices
