```python
import random
import json

class IntArray:
    def __init__(self, length=10):
        self.data = [None] * length
        for i in range(length):
            self.data[i] = random.randint(1, 100)

def build_json(custom_object):
    json_obj = {}

    def recursive_serialization(val, key=None):
        if isinstance(val, list):
            serialized = []
            for i, v in enumerate(val):
                serialized.append(recursive_serialization(v, str(i)))
            return serialized

        if isinstance(val, IntArray):
            json_obj[key] = {'type': 'intArray', 'length': len(val.data), 'data': [str(d) for d in val.data]}
            return None

        json_obj[key] = val
        return None

    recursive_serialization(custom_object)
    return json.dumps(json_obj)

def main():
    custom_object = {'name': 'example', 'intArray': IntArray()}
    print(build_json(custom_object))

if __name__ == ""__main__"":
    main()
```

