import json
import re

def interpret_message(msg):
    pattern = r'(SET|GET|UPDATE),(?:(?:key)(?:=(.+))?)'
    matches = re.findall(pattern, msg)

    response = {'message': 'error'}

    for match in matches:
        keyword, key, value = match

        if keyword == ""SET"":
            response['message'] = 'success' if value else 'error'
        elif keyword == ""GET"" and value:
            response['value'] = value
        elif keyword == ""UPDATE"":
            response['message'] = 'success' if value else 'error'
            response['old_value'] = response.get('value', None)
            response['new_value'] = value

    return json.dumps(response)
