304,"Create a Python class named FileValidator tasked with handling file integrity checks. Include functionalities for setting up the file, calculating its MD5 hash, and ensuring integrity through comparison with a reference hash. Additionally, develop a test function to authenticate the class's implementation across multiple files and hash values.",680,,"['```python
import hashlib
import os
import unittest

class FileValidator:
    def __init__(self, file_path):
        self.file_path = file_path
        self.hash = None

    def calculate_md5(self):
        if not os.path.exists(self.file_path) or not os.path.isfile(self.file_path):
            raise FileNotFoundError(f""File {self.file_path} does not exist."")

        with open(self.file_path, 'rb') as file:
            md5 = hashlib.md5()
            while chunk := file.read(8192):
                md5.update(chunk)
            self.hash = md5.hexdigest()
        return self.hash

    def check_integrity(self, reference_hash):
        if self.hash is None:
            raise ValueError(""MD5 hash must be calculated before checking integrity."")
        return self.hash == reference_hash

class TestFileValidator(unittest.TestCase):
    def setUp(self):
        self.file_validator = FileValidator('test_file.txt')
        self.reference_hash = '098f6bcd4621d373cade4e832627b4f6'  # Replace with actual reference hash

    def test_calculate_md5(self):
        self.file_validator.calculate_md5()
        expected_hash = self.reference_hash
        self.assertEqual(self.file_validator.hash, expected_hash)

    def test_check_integrity(self):
        self.assertTrue(self.file_validator.check_integrity(self.reference_hash))
