def median(data):
    sorted_data = sorted(data)
    n = len(sorted_data)
    if n % 2 == 0:
        mid1 = int(n / 2)
        return (sorted_data[mid1 - 1].value + sorted_data[mid1].value) / 2
    else:
        mid = int(n / 2)
        return sorted_data[mid].value

def main():
