        data.id, data.stock = int(data.id), int(data.stock)
        data.price = float(data.price)
        data.value = median([data.stock, data.price])
    print(*[f""{item.id}, {item.stock}, {item.price}, {item.value}"" for item in item_data), sep=""\n"")

if __name__ == ""__main__"":
    main()
