import sqlite3
import logging
from random import randint, choice
import sys

class PLAYLIST_TRACK_T:
    def __init__(self, track_id, artist, title, duration):
        self.track_id = track_id
        self.artist = artist
        self.title = title
        self.duration = duration

def generate_unique_track_id():
    while True:
        track_id = str(int(time.time() * 1000))
        if not any(t.track_id == track_id for t in PLAYLIST_TRACKS):
            return track_id

def generate_random_duration(min_duration, max_duration):
    return randint(min_duration, max_duration)

PLAYLIST_TRACKS = []
ERROR_CODES = {1: 'Duplicate Track ID', 2: 'Missing Artist', 3: 'Missing Title'}

def create_track(artist, title, min_duration=180, max_duration=360):
    track_id = generate_unique_track_id()
    if not artist or not title:
        logging.error(f'Error code {ERROR_CODES[2]}')
        return None

    duration = generate_random_duration(min_duration, max_duration)
    total_duration += duration
    if total_duration > 5 * 60 * 60:
        logging.error('Total playlist duration exceeded 5 hours')
        return None

    track = PLAYLIST_TRACK_T(track_id, artist, title, duration)
    PLAYLIST_TRACKS.append(track)
    return track

def save_tracks_to_db(tracks):
    conn = sqlite3.connect('playlist.db')
    c = conn.cursor()
    c.execute('''CREATE TABLE IF NOT EXISTS TRACKS (TRACK_ID TEXT PRIMARY KEY)''')
    for track in tracks:
        c.execute(""INSERT INTO TRACKS (TRACK_ID) VALUES (?)"", (track.track_id,))
    conn.commit()
    conn.close()

def generate_playlist_tracks(num_tracks=10, min_duration=180, max_duration=360):
    PLAYLIST_TRACKS = []

    def create_track_threaded(artist, title):
        track = create_track(artist, title, min_duration, max_duration)
        if track:
            PLAYLIST_TRACKS.append(track)

    total_duration = 0
    thread_pool = []

    for _ in range(num_tracks):
        artist = choice(TOP_ARTISTS_YEAR)
        title = choice(TOP_TITLES_YEAR)
        t = threading.Thread(target=create_track_threaded, args=(artist, title))
        thread_pool.append(t)
        t.start()

    for t in thread_pool:
        t.join()

    save_tracks_to_db(PLAYLIST_TRACKS)

def test_function():
    validity_criteria = [
        lambda track: len(track.artist) > 3,
        lambda track: len(track.title) > 3,
        lambda track: not any(t2.track_id == track.track_id for t2 in PLAYLIST_TRACKS if t2 != track),
    ]

    generated_tracks = generate_playlist_tracks()
    for track in generated_tracks:
        for criterion in validity_criteria:
            if not criterion(track):
                logging.error('Track validation failed')
                return False
    return True

TOP_ARTISTS_YEAR = [...]
