import struct
import os
from typing import Tuple

class Record:
    def __init__(self, id: int, timestamp: str, value: float):
        self.id = id
        self.timestamp = timestamp
        self.value = value

def decode_binary_file(filename: str, total_records: int, valid_records: int, avg_value: float) -> Tuple[int, float]:
    try:
        with open(filename, 'rb') as file:
            while True:
                record = file.read(record_size)
                if not record:
                    break

                id_, timestamp_, value_ = struct.unpack('>I40s f', record)

                if id_ == 0 and len(timestamp_.decode()) == 0 and not math.isclose(value_, float('nan')):
                    valid_records += 1
                    avg_value += value_

    except FileNotFoundError:
        print(""Error: Binary file not found."")
        return total_records, avg_value

    if valid_records > 0:
        avg_value /= valid_records
        print(f'Average Value: {avg_value}')
    else:
        print('No valid records found.')

    file.close()
    return total_records, avg_value

record_size = 44 # (ID(int) + timestamp(string) + value(float)) size in bytes
```
