import argparse
import json
import os

def load_tasks_from_file(file_path):
    if not os.path.exists(file_path):
        return []
    with open(file_path, 'r') as file:
        return json.load(file)

def save_tasks_to_file(tasks, file_path):
    with open(file_path, 'w') as file:
        json.dump(tasks, file)

def list_tasks(tasks):
    for index, task in enumerate(tasks):
        print(f""{index+1}. {task}"")

def add_task(tasks, task_text):
    tasks.append(task_text)
    save_tasks_to_file(tasks, args.file)

def delete_task(tasks, task_index):
    if 1 <= task_index <= len(tasks):
        deleted_task = tasks.pop(task_index - 1)
        save_tasks_to_file(tasks, args.file)
        return deleted_task
    return None

parser = argparse.ArgumentParser(description=""Todo List CLI"")

parser.add_argument('-l', '--list', action='store_true', help=""List tasks"")
parser.add_argument('-a', '--add', type=str, help=""Add a task"")
parser.add_argument('-d', '--delete', type=int, help=""Delete a specific task"")
parser.add_argument('-f', '--file', type=str, default=None,
                    help=""Path to a file for persistent storage"")

args = parser.parse_args()

tasks = load_tasks_from_file(args.file) if args.file else []

if args.list:
    list_tasks(tasks)
elif args.add:
    add_task(tasks, args.add)
elif args.delete:
    deleted_task = delete_task(tasks, args.delete)
    if deleted_task:
        print(f""Deleted: {deleted_task}"")
else:
    parser.print_help()
