            'power_level': self.power_level,
            'is_connected': self.is_connected,
            'connection_history': self.connection_history
        }

def generate_devices(num_devices):
    devices = []
    for _ in range(num_devices):
        device_id = str(uuid.uuid4())
        device_name = f""Device_{device_id[-6:]}""
        device_address = f""{device_id[:2]}:{device_id[2:4]}:{device_id[4:6]}:{device_id[6:8]}:{device_id[8:10]}:{device_id[10:]}""

        device_entity = BluetoothDevice(device_name, device_address)

        devices.append(device_entity.to_dict())

    return devices

def connect_device(device_list, index):
    if 0 <= index < len(device_list):
        device_to_connect = device_list[index]

