            current_time = datetime.now().strftime(""%Y-%m-%d %H:%M:%S"")

            if len(device_to_connect['connection_history']) > 5:
                del device_to_connect['connection_history'][0]

            device_to_connect['connection_history'].append((current_time, ""Connected""))

def disconnect_device(device_list, index):
    if 0 <= index < len(device_list):
        device_to_disconnect = device_list[index]

        if device_to_disconnect['is_connected']:
            print(f""Disconnecting from {device_to_disconnect['name']}"")
