from collections.abc import Iterable
import re
html_colors = {
    ""#FFF"": ""white"",
    ""#FFD"": ""antiquewhite1"",
    ""#F00"": ""red"",
    ""#0F0"": ""lime"",
    ""#00F"": ""blue"",
    # Add more colors as needed...
}

def hex_to_html(hex_colors: Iterable[str]):
    color_names = []
    for hex in hex_colors:
        try:
            hex_stripped = re.sub('^#', '', hex)
            if len(hex_stripped) == 6:
                r, g, b = [int(x, 16) for x in (hex_stripped[0:2], hex_stripped[2:4], hex_stripped[4:6])]
                closest_name = min([abs((r * 299/256 + g * 587/256 + b * 114/256) - x) for x, name in html_colors.items()], key=min)
                color_names.append(html_colors[list(html_colors.keys())[color_closest]])
            else:
                color_names.append(""invalid"")
        except ValueError:
            color_names.append(""invalid"")
    return color_names
