0,"Create a Python function that produces a list of Network Resource Allocation Profile (NRAP) entities. Each NRAP should encapsulate randomly chosen network protocols, resource allocation parameters, and associated network addresses. The function must access and parse configuration files from a designated directory using the os library, akin to the previous task's method involving file system interactions. The NRAP instances should retain file paths as part of their configuration for future reference.",680,,"['```python
import os
import random
from typing import List

class Nrap:
    def __init__(self, file_path):
        self.file_path = file_path

    @staticmethod
    def parse_config(file_path):
        with open(file_path) as config_file:
            lines = config_file.readlines()
            protocol = random.choice([line.strip() for line in lines if ""protocol"" in line])
            resource_params = {k.replace("" "", ""_"").lower(): v for k, v in [line.split("":"") for line in lines if ""="" in line]}
            network_address = random.choice([line.strip() for line in lines if ""network_address"" in line])
        return protocol, resource_params, network_address

    def generate_nrap(file_path):
        protocol, resource_params, network_address = Nrap.parse_config(file_path)
        return {""protocol"": protocol, ""resource_params"": resource_params, ""network_address"": network_address}

def create_nraps(directory: str) -> List[Nrap]:
    nraps = []
    for file in os.listdir(directory):
        if file.endswith("".conf""):
            nrap_file_path = os.path.join(directory, file)
            nraps.append(Nrap(nrap_file_path))
    nraps_data = [nrap.generate_nrap(nrap_file_path) for nrap in nraps]
    return nraps_data
