from datetime import datetime

class EnhancedDCPacketMetadata(DCPacketMetadata):
    def __init__(self, session_id, target_ip, port, timestamp=datetime.now()):
        super().__init__(session_id, target_ip, port)
        self.timestamp = timestamp

def create_unique_session_ids(num_packets):
    if num_packets > 1:
        seen_ids = set()

        while len(seen_ids) < num_packets:
            new_session_id = create_session_id()
            if new_session_id not in seen_ids:
                seen_ids.add(new_session_id)

        return list(seen_ids)

    else:
        return [create_session_id()]

def generate_dcpacket_metadata_with_timestamps(num_packets, ip_targets=None):
    if ip_targets is None:
        ip_targets = [socket.gethostbyname(socket.gethostname())] * num_packets

    unique_sessions = create_unique_session_ids(num_packets)

    packet_list_with_timestamps = []

    for index in range(len(unique_sessions)):

        if len(unique_sessions) > len(ip_targets):
            raise ValueError(""Insufficient number of IP targets provided."")

        packet_list_with_timestamps.append(EnhancedDCPacketMetadata(
            unique_sessions[index],
            ip_targets[index],
            generate_random_port(),
            datetime.now()
        ))

    return packet_list_with_timestamps
