import random
from ipaddress import IPv4Network, IPv4Address
from eth-lib.mac_addr import mac_text

def generate_random_ip():
    return str(IPv4Address(random.randint(0, 0xFFFFFFFF)))

def generate_random_subnet_mask():
    return str(IPv4Network('255.255.255.0').broadcast_address)

def generate_random_mac():
    return mac_text().hex

def create_nfv_instance():
    nfv_types = ['router', 'switch', 'load balancer']

    type_, ip, subnet_mask, mac = map(str, zip(*[create_nfv_instance for _ in range(1)]))

    type_ = random.choice(nfv_types)
    ip = generate_random_ip()
    subnet_mask = generate_random_subnet_mask()
    mac = generate_random_mac()

    return {
        'type': type_,
        'IP address': ip,
        'Subnet Mask': subnet_mask,
        'MAC Address': mac
    }

if __name__ == ""__main__"":
    for _ in range(10):
        print(create_nfv_instance())
```

