import socket
import threading

def receive_data(sock):
    try:
        while True:
            data = sock.recv(1024).decode()
            if not data:
                break
            print(f""Received from server: {data}"")
    except Exception as e:
        print(f""Error receiving data: {e}"")

def send_message(sock, message):
    try:
        sock.sendall(message.encode())
    except Exception as e:
