0,"Create a new program that allows users to establish a secure connection with a remote server using SSL/TLS encryption. Implement a function called `secure_connect` which takes the server's IP address and port number as input parameters. This function should use the `ssl` library in Python to connect to the server securely. Additionally, include functions for sending and receiving messages through this secure connection. The program should also provide a user interface where users can input the server details, and display received messages on the console. Ensure error handling is included for potential SSL/TLS connection issues or timeouts.",590,,"['```python
import socket
import ssl
from threading import Thread

def secure_connect(ip, port):
    context = ssl.create_default_context()
    with socket.create_connection((ip, port)) as sock:
        ssl_sock = context.wrap_socket(sock, server_hostname=ip)
        return ssl_sock

def send_message(ssl_sock, message):
    try:
        ssl_sock.sendall(message.encode())
    except Exception as e:
        print(""Error sending message:"", str(e))

def receive_message(ssl_sock):
    try:
        response = ssl_sock.recv(1024).decode()
        return response
    except Exception as e:
        print(""Error receiving message:"", str(e))
        return None

def user_input():
    ip = input(""Enter the server IP: "")
    port = int(input(""Enter the server port number: ""))
    return ip, port

def main():
    ip, port = user_input()
    ssl_sock = secure_connect(ip, port)

    if not ssl_sock:
        print(""Failed to connect."")
        return

    def receive():
        while True:
            message = receive_message(ssl_sock)
            if message:
                print(message)

    thread = Thread(target=receive, daemon=True)
    thread.start()

    message = input(""Enter your message: "")
    send_message(ssl_sock, message)

if __name__ == ""__main__"":
    main()
```
