from sqlite3 import connect, CurrencyError

def profile_generator(email_length=10, password_strength=6):
    db = connect('profiles.db')
    c = db.cursor()
    c.execute('CREATE TABLE IF NOT EXISTS profiles (id INTEGER PRIMARY KEY, email TEXT UNIQUE, password TEXT, creation TIMESTAMP DEFAULT CURRENT_TIMESTAMP, last_modification TIMESTAMP)')

    emails = {'admin': f'{random_email(""admin"")}', 'standard': f'{random_email(""standard"")}'}

    for user_type in ['admin', 'standard']:
        for _ in range(250):  # Adjust this number to generate up to 500 profiles
            try:
                hashed_password = hash_password(f'{user_type}{random_string(password_strength)}')
                c.execute('INSERT INTO profiles (email, password) VALUES (?, ?)', (emails[user_type], hashed_password))
                db.commit()
            except CurrencyError:
                print(f'Error generating profile for {user_type}: email or password already exists')

    def random_email(user_type):
        return f'{user_type}+{random_string(email_length)}@example.com'

    def random_string(length):
        letters = string.ascii_lowercase + string.digits
        return ''.join(random.choice(letters) for _ in range(length))

    def hash_password(password):
        salt = random_string(32)
        hashed = hashlib.pbkdf2_hmac('sha256', password.encode(), salt.encode(), 100000).hex() + ':' + salt
        return hashed

