import re
import json

def interpret_message(msg):
    keywords = {'SET': '', 'GET': '', 'UPDATE': ''}
    pattern = r'(\w+,\s*key=([\w\s]+))(?:,\s*(?:value=([\w\s]+)))?'
    result = re.search(pattern, msg)
    if result:
        keyword, key, value = result.groups()
        keywords[keyword] = f'{{""key"": ""{key}"", ""value"": ""{value}""}}' if value else f'{{""key"": ""{key}""}}'
        response = json.loads(keywords['GET']) if keyword == 'GET' else {'message': 'success'}
    else:
        response = {'error': 'Invalid message format'}
    return response
