object ThemeCache {
    private const val TAG = ""ThemeCache""
    private lateinit var themeCacheDir: File
    private lateinit var themeBitmap: Bitmap

    fun initialize() {
        if (!themeCacheDir.exists()) {
            themeCacheDir = CacheManager.getCacheDirectory(context).apply { mkdirs() }
        }
    }

    fun getThemeBitmap(): Bitmap? {
        synchronized(this) {
            if (themeBitmap == null || !themeBitmap.isRecycled()) {
                themeBitmap = BitmapFactory.decodeStream(FileInputStream(getThemeFilePath()))
                themeBitmap.recycle()
                themeBitmap = null
            }
        }
        return themeBitmap
    }

    private fun getThemeFilePath(): File {
        return File(themeCacheDir, ""theme.png"")
    }

    fun putThemeBitmap(bitmap: Bitmap) {
        bitmap.compress(PNG, 100, FileOutputStream(getThemeFilePath()))
        themeBitmap = bitmap
    }
}
