import sys, random

class ITEM_DATA_STRUCT_T(object):
    def __init__(self, id, stock, price, median):
        self.id = id
        self.stock = stock
        self.price = price
        self.median = median

def read_file(filename):
    items = []
    with open(filename) as f:
        for line in f:
            fields = line.strip().split(',')
            id, stock, price = int(fields[0]), int(fields[1]), float(fields[2])
            median = calculate_median(fields[3:5])
            items.append(ITEM_DATA_STRUCT_T(id, stock, price, median))
    return items

def calculate_median(numbers):
    sorted_numbers = sorted(numbers)
    length = len(sorted_numbers)
    if length % 2 == 0:
        return (sorted_numbers[length//2 - 1] + sorted_numbers[length//2]) / 2
    else:
        return sorted_numbers[length//2]

if __name__ == ""__main__"":
    if len(sys.argv) != 2:
        print(""Usage: python script.py <file_path>"")
        sys.exit(1)

    items = read_file(sys.argv[1])
